"""Apply the review's bibliographic corrections; preserve old metadata in history."""
import json
from parse_catalogue import ROOT, RAW, RUN, sha, write_json

def main():
    s=json.loads((RUN/'history/2026-10-07-before-review-response/sources.json').read_text(encoding='utf8'))
    by={x['id']:x for x in s['sources']}
    by['hemmy1931']['venue']='In John Marshall, Mohenjo-Daro and the Indus Civilization, vol. II, pp. 589–598'
