    by['lago_cardarelli_ialongo2024']['authors'][1]='Lorenzo Cardarelli'
    by['bibby1970']['title']='»… EFTER DILMUN NORM«'
    by['bibby1970']['normalized_title']='«… efter Dilmun norm»'
    by['bibby1970']['title_witness']='Printed p. 345 (PDF p. 6), visually checked using local review-tmp/bibby-p6.png; printed guillemets are ordered »…«.'
    by['ascalone2022']['contributors']=[{'name':'Jan Tavernier','role':'contribution; title-page wording'}]
    by['ascalone2022']['locations'] += ['Susa Harappan and Western lists pp. 69–70','Heavier Dholavira group pp. 169–171: 95 objects, reported mean 14.44 g','Bibliography p. 187: Ascalone 2018c and 2021a']
    by['ascalone2022']['established']='Already analyzes the catalogue with CQA and typological subdivisions; interprets a c.13.6 g Harappan group and 95 heavier Dholavira weights (reported mean 14.44 g), Rakhigarhi c.14.43 g, Western and Mesopotamian groups at Dholavira, and Susa Harappan-standard and Western lists. These attributions precede this reanalysis.'
    by['vahia_yadav2007']['established']='Numerical reanalysis reports about 6% within-class fluctuation and a 0.89 g small base; ratio 16 corresponds arithmetically to 14.24 g. It gives binary-related small levels and decimal-related large levels. Its class statistic and transcription assumptions differ from this package signal CV.'
    hemmy38='https://rws.xoba.com/indus_weights/Hemmy-1938-weights-Mohenjodaro-Mackay.pdf'
    hemmy43='https://rws.xoba.com/indus_weights/Hemmy_Hall-1943-weights-Chanhudaro-Mackay.pdf'
    by['hemmy1938'].update(url=hemmy38,opened=True,full_text_opened=True,access='Full primary scan downloaded and opened during review response',local_path='data/raw/2026-10-06-weight-metrology/revision-literature/hemmy-1938.pdf',locations=['Printed pp. 601–602: Tables I–III, mean base 0.8565/0.857 g and ratio 16 values 13.704/13.712 g','Printed pp. 601–612 (PDF pp. 2–13)'],established='Analyzes 220 additional weights; condition rules, larger levels, the 8/3 fractional group, and combined Mohenjo-daro/Harappa observations. The conventional ratio-16 level is close to 13.70 g.')
    entries=[
      dict(id='hemmy1938b',authors=['A. S. Hemmy'],year=1938,title='Relation to Egyptian and Susian weights',venue='In E. J. H. Mackay, Further Excavations at Mohenjo-Daro, vol. I, pp. 672–678',url=hemmy38,opened=True,full_text_opened=True,access='Full primary scan downloaded and opened',local_path=by['hemmy1938']['local_path'],locations=['Printed pp. 672–674 (PDF pp. 14–16): distribution and Susa ambiguity','Printed p. 675 Table IX (PDF p. 17): Susa objects and alternative daric ratios'],established='Tests Egyptian/Susian links, derives 13.625 g from a frequency curve, and compares Susa objects under Indus and local ratios. This is a precedent for mass-attribution ambiguity.'),
      dict(id='hemmy1943',authors=['A. S. Hemmy'],year=1943,title='Weights at Chanhu-daro',venue='In E. J. H. Mackay, Chanhu-Daro Excavations 1935-36, New Haven: American Oriental Society, pp. 236–239 (Hemmy section); Ascalone bibliography cites pp. 236–243',url=hemmy43,opened=True,full_text_opened=True,access='Full primary extract downloaded and opened, including adjacent Hall section',local_path='data/raw/2026-10-06-weight-metrology/revision-literature/hemmy-hall-1943.pdf',locations=['Printed pp. 236–237 (PDF pp. 2–3): selection and distribution curves','Printed p. 239 (PDF p. 5): Hall section starts at bottom of page'],established='Reports a modal estimate of 13.63 g for combined observations after excluding doubtful ratios and masses below 6 g; explicitly describes smaller weights as less accurate. The below-6 g exclusion belongs to that modal comparison, not to every historical table.'),
      dict(id='hall1943',authors=['Adelia Ripley Hall'],year=1943,title='The Cube Weights in Boston',venue='In E. J. H. Mackay, Chanhu-Daro Excavations 1935-36, New Haven: American Oriental Society, pp. 239–247',url=hemmy43,opened=True,full_text_opened=True,access='Adjacent primary section in downloaded Hemmy/Hall extract',local_path='data/raw/2026-10-06-weight-metrology/revision-literature/hemmy-hall-1943.pdf',locations=['Printed pp. 241–244 (PDF pp. 7–10): fractional ratios and precise reweighing'],established='Describes fractional ratios supplementary to the ordinary series, including 2/3 and 1/3 of the smallest level and other thirds, and repeated precise weighing. These precede tests of extra fractional denominations.'),
      dict(id='ascalone2018c',authors=['Enrico Ascalone'],year=2018,title='Weights at Rakhigarhi and in the Ghaggar Basin',venue='Annali dell’Istituto Italiano di Numismatica 64, pp. 9–32',url='https://iris.unisalento.it/handle/11587/476945',opened=True,full_text_opened=False,access='Institutional metadata and publisher contents opened; original PDF restricted, no request submitted',locations=['Ascalone 2022 pp. 123–124 summary and p. 187 bibliography','Publisher contents Annali 64 (2018); institutional item labels date 2019'],established='As summarized and credited in Ascalone 2022, precedes the Rakhigarhi/Ghaggar heavier-unit argument and regional metrology discussion. Detailed original methods remain unverified.',metadata_urls=['https://www.istitutoitalianonumismatica.it/sommari/','https://cordis.europa.eu/project/id/648055/results'],limits='2018 is the journal issue year; institutional repository date is 2019.'),
      dict(id='ascalone2021a',authors=['Enrico Ascalone'],year=2021,title='Made in Indus, Made in Oman, and Made in Susiana: Meluhha and Makkan at Kish, Telloh, and Susa as seen from Weights and Ingots',venue='In Marc Lebeau (ed.), Identity, Diversity & Contact: from the Southern Balkans to Xinjiang, from the Upper Palaeolithic to Alexander, International Congress The East 1, Turnhout: Brepols, pp. 93–112 (Ascalone 2022 bibliography)',url='https://www.brepols.net/products/IS-9782503589497-1',opened=True,full_text_opened=False,access='Publisher contents and ERC publication metadata opened; original chapter not recovered',locations=['Publisher contents, chapter title','Ascalone 2022 pp. 69–70 attribution and p. 187 bibliography'],established='Ascalone 2022 p. 70 credits this work for locally produced Susa weights following Harappan standards. The broader study concerns weights/ingots at Kish, Telloh and Susa; detailed chapter claims are not independently audited.',limits='CORDIS gives pp. 93–111; Ascalone bibliography gives pp. 93–112. Publisher contents has no chapter page range; discrepancy retained.'),
      dict(id='hendrickx_baudot1972',authors=['M.-P. Hendrickx-Baudot'],year=1972,title='The weights of the Harappa-culture',venue='Orientalia Lovaniensia Periodica 3, pp. 5–34',url=None,opened=False,full_text_opened=False,access='Bibliographic reference read in opened Ascalone 2022 p. 197; exact-title live search did not recover original article',metadata_or_citation_url=by['ascalone2022']['url'],locations=['Ascalone 2022 p. 197 bibliography and p. 123 retrospective'],established='Earlier Harappan weight-system study; detailed models and numerical claims remain unverified. No novelty claim against an unread original is supported.')]
    s['sources'].extend(entries)
    for e in s['sources']:
        e['search_snippet_only']=False
        e['original_text_access']='full text' if e.get('full_text_opened') else 'partial text or metadata/citation; see access'
        e.setdefault('metadata_or_citation_url',e.get('url') or by['ascalone2022']['url'])
        if e.get('local_path') and (ROOT/e['local_path']).is_file():e['sha256']=sha(ROOT/e['local_path'])
